1	import "server-only";
2	import { and, eq, sql } from "drizzle-orm";
3	import { db, schema as s } from "@/db";
4	import type { Tx } from "@/db";
5	
6	export type OutboxMessage = {
7	  businessId: string;
8	  topic: string;
9	  payload: Record<string, unknown>;
10	  /** Natural key; a second enqueue with the same key is a no-op. */
11	  dedupeKey?: string;
12	  /** Delay delivery until this instant (reminders, offers with a deadline). */
13	  availableAt?: Date;
14	  maxAttempts?: number;
15	};
16	
17	/**
18	 * Enqueue inside the caller's transaction. Never call this with the global
19	 * `db` when a business row is being written — that is the whole point of the
20	 * pattern: message and change commit together or not at all.
21	 */
22	export async function enqueue(tx: Tx, msg: OutboxMessage): Promise<void> {
23	  await tx
24	    .insert(s.outbox)
25	    .values({
26	      businessId: msg.businessId,
27	      topic: msg.topic,
28	      payload: msg.payload,
29	      dedupeKey: msg.dedupeKey ?? null,
30	      availableAt: msg.availableAt ?? new Date(),
31	      maxAttempts: msg.maxAttempts ?? 5,
32	    })
33	    .onConflictDoNothing({ target: s.outbox.dedupeKey });
34	}
35	
36	/** Drop a scheduled message that is no longer wanted (booking cancelled…). */
37	export async function cancelByDedupeKey(tx: Tx, dedupeKey: string): Promise<void> {
38	  await tx
39	    .update(s.outbox)
40	    .set({ status: "cancelled", updatedAt: new Date() })
41	    .where(and(eq(s.outbox.dedupeKey, dedupeKey), eq(s.outbox.status, "pending")));
42	}
43	
44	export type ClaimedMessage = typeof s.outbox.$inferSelect;
45	
46	/** How long a claimed message stays reserved before another worker may retry it. */
47	export const LEASE_SEC = 60;
48	
49	/** Raw SQL returns snake_case columns; drizzle's select does not. Bridge them. */
50	type OutboxRow = {
51	  id: string;
52	  business_id: string;
53	  topic: string;
54	  payload: unknown;
55	  dedupe_key: string | null;
56	  available_at: Date;
57	  status: (typeof s.outboxStatuses)[number];
58	  attempts: number;
59	  max_attempts: number;
60	  last_error: string | null;
61	  created_at: Date;
62	  updated_at: Date;
63	};
64	
65	const toMessage = (r: OutboxRow): ClaimedMessage => ({
66	  id: r.id,
67	  businessId: r.business_id,
68	  topic: r.topic,
69	  payload: r.payload,
70	  dedupeKey: r.dedupe_key,
71	  availableAt: r.available_at,
72	  status: r.status,
73	  attempts: r.attempts,
74	  maxAttempts: r.max_attempts,
75	  lastError: r.last_error,
76	  createdAt: r.created_at,
77	  updatedAt: r.updated_at,
78	});
79	
80	/**
81	 * Atomically claim up to `limit` due messages.
82	 *
83	 * Two mechanisms, doing different jobs:
84	 *  - FOR UPDATE SKIP LOCKED keeps simultaneous claimers off each other's rows
85	 *    inside the statement — a locked row is invisible rather than blocking.
86	 *  - Flipping the row to 'processing' with `available_at` pushed out by
87	 *    LEASE_SEC keeps it claimed *after* the statement commits. Row locks end
88	 *    with the statement; without the lease a second worker a millisecond later
89	 *    would happily claim the same message again.
90	 *
91	 * The lease doubles as crash recovery: a worker that dies mid-delivery leaves
92	 * the row reserved only until the lease lapses, then it is retried.
93	 */
94	export async function claim(limit: number): Promise<ClaimedMessage[]> {
95	  const { rows } = await db.execute<OutboxRow>(sql`
96	    WITH due AS (
97	      SELECT id FROM outbox
98	      WHERE status IN ('pending', 'processing') AND available_at <= now()
99	      ORDER BY available_at
100	      FOR UPDATE SKIP LOCKED
101	      LIMIT ${limit}
102	    )
103	    UPDATE outbox o
104	    SET attempts    = o.attempts + 1,
105	        status      = 'processing',
106	        available_at = now() + (${LEASE_SEC} || ' seconds')::interval,
