type WaitlistEntry = typeof s.waitlistEntries.$inferSelect;

/** Hands an offer's slot to the next person; the worker also releases its hold. */
async function passSlotOn(tx: Tx, entry: WaitlistEntry): Promise<void> {
  const startMs = entry.offerSlotStartAt!.getTime();
  await enqueue(tx, {
    businessId: entry.businessId,
    topic: "waitlist.slot_freed",
    payload: {
      staffId: entry.offerStaffId,
      serviceId: entry.serviceId,
      startMs,
      endMs: entry.offerSlotEndAt!.getTime(),
      releaseHoldToken: entry.offerHoldToken,
    } satisfies FreedSlot,
    dedupeKey: `waitlist.refree:${entry.id}:${startMs}`,
  });
}

/** Called by the worker when an offer's deadline passes. */
export async function expireOffer(entryId: string): Promise<void> {
  const [entry] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.id, entryId));
  if (!entry || entry.status !== "offered") return; // accepted or cancelled already

  await db.transaction(async (tx) => {
    const [lapsed] = await tx
      .update(s.waitlistEntries)
      .set({ status: "expired", offerToken: null, offerExpiresAt: null })
      .where(and(eq(s.waitlistEntries.id, entryId), eq(s.waitlistEntries.status, "offered")))
      .returning({ id: s.waitlistEntries.id });
    if (lapsed) await passSlotOn(tx, entry);
  });
}

export type DeclineResult = { ok: true } | { ok: false; error: "not_found" | "expired" };

/**
 * The client turns the offer down. The status flip is the single point of
 * agreement: however many taps or processes race here, only one of them
 * enqueues the next offer.
 */
export async function declineOffer(token: string): Promise<DeclineResult> {
  const [entry] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.offerToken, token));
  if (!entry) return { ok: false, error: "not_found" };
  if (entry.status === "declined") return { ok: true };
  if (
    entry.status !== "offered" ||
    !entry.offerExpiresAt ||
    entry.offerExpiresAt.getTime() < Date.now()
  ) {
    return { ok: false, error: "expired" };
  }

  const declined = await db.transaction(async (tx) => {
    const [flipped] = await tx
      .update(s.waitlistEntries)
      .set({ status: "declined" })
      .where(and(eq(s.waitlistEntries.id, entry.id), eq(s.waitlistEntries.status, "offered")))
      .returning({ id: s.waitlistEntries.id });
    if (!flipped) return false;

    await tx.insert(s.auditLog).values({
      businessId: entry.businessId,
      action: "waitlist.declined",
      entity: "waitlist_entry",
      entityId: entry.id,
    });
    await passSlotOn(tx, entry);
    return true;
  });
  if (declined) return { ok: true };

  // Lost a race with another tap or the deadline; report what actually happened.
  const [current] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.id, entry.id));
  return current?.status === "declined" ? { ok: true } : { ok: false, error: "expired" };
}

const RELEASE_HOLD_IF_OWNED = `
local raw = redis.call('GET', KEYS[1])
if raw and cjson.decode(raw).token == ARGV[1] then
  return redis.call('DEL', KEYS[1])
end
return 0
`;

async function releaseHold(staffId: string, startMs: number, holdToken: string): Promise<void> {
  await redis().eval(RELEASE_HOLD_IF_OWNED, 1, `hold:${staffId}:${startMs}`, holdToken);
}

