  if (!entry) return { ok: false, error: "not_found" };
  if (entry.status === "declined") return { ok: true };
  if (
    entry.status !== "offered" ||
    !entry.offerExpiresAt ||
    entry.offerExpiresAt.getTime() < Date.now()
  ) {
    return { ok: false, error: "expired" };
  }

  const declined = await db.transaction(async (tx) => {
    const [flipped] = await tx
      .update(s.waitlistEntries)
      .set({ status: "declined" })
      .where(and(eq(s.waitlistEntries.id, entry.id), eq(s.waitlistEntries.status, "offered")))
      .returning({ id: s.waitlistEntries.id });
    if (!flipped) return false;

    await tx.insert(s.auditLog).values({
      businessId: entry.businessId,
      action: "waitlist.declined",
      entity: "waitlist_entry",
      entityId: entry.id,
    });
    await passSlotOn(tx, entry);
    return true;
  });
  if (declined) return { ok: true };

  // Lost a race with another tap or the deadline; report what actually happened.
  const [current] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.id, entry.id));
  return current?.status === "declined" ? { ok: true } : { ok: false, error: "expired" };
}

const RELEASE_HOLD_IF_OWNED = `
local raw = redis.call('GET', KEYS[1])
if raw and cjson.decode(raw).token == ARGV[1] then
  return redis.call('DEL', KEYS[1])
end
return 0
`;

async function releaseHold(staffId: string, startMs: number, holdToken: string): Promise<void> {
  await redis().eval(RELEASE_HOLD_IF_OWNED, 1, `hold:${staffId}:${startMs}`, holdToken);
}

