describe("declining an offer", () => {
  async function offerToFirstOfTwo() {
    const booked = await book();
    await join("+77012222222");
    await join("+77013333333");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    await drainOnce();
    return (await entries()).find((r) => r.status === "offered")!;
  }

  it("passes the time to the next client at once and kills the link", async () => {
    const first = await offerToFirstOfTwo();
    expect(await declineOffer(first.offerToken!)).toEqual({ ok: true });

    await drainOnce(); // slot_freed -> next offer
    await drainOnce(); // deliver it

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("declined");
    const second = rows.find((r) => r.status === "offered")!;
    const [client] = await db.select().from(s.clients).where(eq(s.clients.id, second.clientId));
    expect(client.phone).toBe("+77013333333");

    expect(await acceptOffer(first.offerToken!)).toEqual({ ok: false, error: "expired" });
  });

  it("returns the time to public stock when nobody else is waiting", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const only = (await entries()).find((r) => r.status === "offered")!;
    await declineOffer(only.offerToken!);
    await drainOnce();

    expect((await entries()).find((r) => r.id === only.id)!.status).toBe("declined");
    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
  });

  it("declines once however many times it is tapped", async () => {
    const first = await offerToFirstOfTwo();
    await Promise.all([declineOffer(first.offerToken!), declineOffer(first.offerToken!)]);
    expect(await declineOffer(first.offerToken!)).toEqual({ ok: true });

    await drainOnce();
    await drainOnce();

    const offered = (await entries()).filter((r) => r.status === "offered");
    expect(offered).toHaveLength(1);
  });

  it("does nothing to an offer that was already claimed", async () => {
