import { eq } from "drizzle-orm";
import { afterAll, beforeEach, describe, expect, it } from "vitest";
import { db, schema as s } from "@/db";
import { createBooking, createHold, getAvailability, setBookingStatus } from "@/lib/booking";
import { drainOnce } from "@/lib/notify/worker";
import { redis } from "@/lib/redis";
import { atLocal, futureDateISO, resetAll, seedBusiness, type Fixture } from "@/test/fixtures";
import { acceptOffer, declineOffer, expireOffer, joinWaitlist } from "./waitlist";

let f: Fixture;
const date = futureDateISO();
const HH = "12:00";

beforeEach(async () => {
  await resetAll();
  f = await seedBusiness();
});

afterAll(async () => {
  await redis().quit();
});

function slotAt(hhmm = HH) {
  const start = atLocal(date, hhmm, f.business.timezone);
  return { startMs: start, endMs: start + 3600_000 };
}

async function book(phone = "+77010000001", hhmm = HH) {
  const slot = slotAt(hhmm);
  const token = (await createHold(f.master.id, slot, 300))!;
  return createBooking({
    businessId: f.business.id,
    staffId: f.master.id,
    serviceId: f.service.id,
    slot,
    holdToken: token,
    client: { name: "Booked", phone },
  });
}

const join = (phone: string, staffId?: string | null) =>
  joinWaitlist({
    businessId: f.business.id,
    serviceId: f.service.id,
    staffId,
    dateISO: date,
    client: { name: `W-${phone.slice(-4)}`, phone },
  });

async function cancel(bookingId: string) {
  await setBookingStatus({
    businessId: f.business.id,
    bookingId,
    status: "cancelled",
    actorUserId: f.owner.id,
  });
}

const entries = () => db.select().from(s.waitlistEntries);
const messages = () => db.select().from(s.messageLog);

describe("joining", () => {
  it("records the client and the requested day", async () => {
    await join("+77011111111");
    const [entry] = await entries();
    expect(entry.status).toBe("waiting");
    expect(entry.dateISO).toBe(date);

    const [client] = await db.select().from(s.clients);
    expect(client.phone).toBe("+77011111111");
  });

  it("reuses an existing client for the same phone", async () => {
    await join("+77011111111");
    await join("+77011111111");
    expect(await db.select().from(s.clients)).toHaveLength(1);
    expect(await entries()).toHaveLength(2);
  });
});

describe("offering a freed slot", () => {
  it("offers to the longest-waiting client and holds the slot for them", async () => {
    const booked = await book();
    await join("+77012222222"); // first in line
    await join("+77013333333");

    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce(); // slot_freed -> offer
    await drainOnce(); // deliver the offer SMS

    const rows = await entries();
    const offered = rows.filter((r) => r.status === "offered");
    expect(offered).toHaveLength(1);
    expect(offered[0].offerToken).toBeTruthy();

    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, offered[0].clientId));
    expect(client.phone).toBe("+77012222222");

    // Held for them: the public availability no longer shows the slot.
    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).not.toContain(slotAt().startMs);

    const sms = await messages();
    expect(sms.some((m) => m.recipient === "+77012222222" && m.subject.includes("a slot has opened up")))
      .toBe(true);
  });

  it("skips clients who wanted a different master", async () => {
    const [other] = await db
      .insert(s.staff)
      .values({ businessId: f.business.id, name: "Other" })
      .returning();

    const booked = await book();
    await join("+77014444444", other.id); // wants someone else
    await join("+77015555555", null); // any master

    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, offered.clientId));
    expect(client.phone).toBe("+77015555555");
  });

  it("does nothing when nobody is waiting", async () => {
    const booked = await book();
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    expect(await entries()).toHaveLength(0);

    // Slot returns to public stock.
    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
  });
});

describe("accepting an offer", () => {
  it("turns the offer into a booking", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    const result = await acceptOffer(offered.offerToken!);
    expect(result.ok).toBe(true);

    const confirmed = await db
      .select()
      .from(s.bookings)
      .where(eq(s.bookings.status, "confirmed"));
    expect(confirmed).toHaveLength(1);
    expect((await entries())[0].status).toBe("booked");
  });

  it("refuses an unknown or already-used token", async () => {
    expect(await acceptOffer("nope")).toEqual({ ok: false, error: "not_found" });
  });

  it("refuses once the deadline has passed", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    await db
      .update(s.waitlistEntries)
      .set({ offerExpiresAt: new Date(Date.now() - 1000) })
      .where(eq(s.waitlistEntries.id, offered.id));

    expect(await acceptOffer(offered.offerToken!)).toEqual({ ok: false, error: "expired" });
  });
});

describe("offer expiry moves down the queue", () => {
  it("passes the slot to the next person when the first does not answer", async () => {
    const booked = await book();
    await join("+77012222222"); // first
    await join("+77013333333"); // second

    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const first = (await entries()).find((r) => r.status === "offered")!;
    await expireOffer(first.id);
    await drainOnce(); // the re-announced slot_freed
    await drainOnce(); // deliver the second offer

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("expired");

    const second = rows.find((r) => r.status === "offered")!;
    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, second.clientId));
    expect(client.phone).toBe("+77013333333");
  });

  it("returns the slot to public stock once the queue is exhausted", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const only = (await entries()).find((r) => r.status === "offered")!;
    await expireOffer(only.id);
    await drainOnce();

    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
  });

  it("leaves an already-accepted offer alone", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    await acceptOffer(offered.offerToken!);
    await expireOffer(offered.id); // deadline fires after acceptance

    expect((await entries())[0].status).toBe("booked");
    expect(await db.select().from(s.bookings).where(eq(s.bookings.status, "confirmed")))
      .toHaveLength(1);
  });
});

import "server-only";
import { randomBytes } from "node:crypto";
import { and, asc, eq, isNull, or } from "drizzle-orm";
import { db, schema as s, type Tx } from "@/db";
import { createBooking, createHold, publishCalendar } from "./booking";
import { enqueue } from "./outbox";
import { redis } from "./redis";

/** How long a client has to accept a freed slot before it moves down the queue. */
export const OFFER_TTL_SEC = 15 * 60;

export type JoinResult = { entryId: string };

export async function joinWaitlist(opts: {
  businessId: string;
  serviceId: string;
  staffId?: string | null;
  dateISO: string;
  client: { name: string; phone: string };
}): Promise<JoinResult> {
  const { businessId, serviceId, staffId, dateISO, client } = opts;

  return db.transaction(async (tx) => {
    const [existing] = await tx
      .select()
      .from(s.clients)
      .where(and(eq(s.clients.businessId, businessId), eq(s.clients.phone, client.phone)));
    const clientRow =
      existing ??
      (
        await tx
          .insert(s.clients)
          .values({ businessId, name: client.name, phone: client.phone })
          .returning()
      )[0];

    const [entry] = await tx
      .insert(s.waitlistEntries)
      .values({
        businessId,
        serviceId,
        staffId: staffId ?? null,
        clientId: clientRow.id,
        dateISO,
      })
      .returning();

    return { entryId: entry.id };
  });
}

export type FreedSlot = {
  staffId: string;
  serviceId: string;
  startMs: number;
  endMs: number;
  /** Hold left by the offer that freed this slot; released before anyone else is offered it. */
  releaseHoldToken?: string;
};

/**
 * Offers a freed slot to the longest-waiting eligible client.
 *
 * Eligibility: same service, same local day, and either no master preference
 * or a preference for the one who freed up. Returns the entry that was offered,
 * or null when nobody is waiting (the slot simply returns to public stock).
 */
export async function offerFreedSlot(businessId: string, slot: FreedSlot): Promise<string | null> {
  if (slot.releaseHoldToken) await releaseHold(slot.staffId, slot.startMs, slot.releaseHoldToken);

  const [business] = await db.select().from(s.businesses).where(eq(s.businesses.id, businessId));
  if (!business) return null;

  const dateISO = new Intl.DateTimeFormat("en-CA", { timeZone: business.timezone }).format(
    slot.startMs,
  );

  const [entry] = await db
    .select()
    .from(s.waitlistEntries)
    .where(
      and(
        eq(s.waitlistEntries.businessId, businessId),
        eq(s.waitlistEntries.serviceId, slot.serviceId),
        eq(s.waitlistEntries.dateISO, dateISO),
        eq(s.waitlistEntries.status, "waiting"),
        or(isNull(s.waitlistEntries.staffId), eq(s.waitlistEntries.staffId, slot.staffId)),
      ),
    )
    .orderBy(asc(s.waitlistEntries.createdAt))
    .limit(1);

  if (!entry) return null;

  // Reserve the slot for them specifically, so a walk-in cannot take it out
  // from under an outstanding offer.
  const token = randomBytes(16).toString("hex");
  const held = await createHold(
    slot.staffId,
    { startMs: slot.startMs, endMs: slot.endMs },
    OFFER_TTL_SEC,
  );
  if (!held) return null; // someone booked it first; nothing to offer

  const expiresAt = new Date(Date.now() + OFFER_TTL_SEC * 1000);

  await db.transaction(async (tx) => {
    await tx
      .update(s.waitlistEntries)
      .set({
        status: "offered",
        offerToken: token,
        offerHoldToken: held,
        offerSlotStartAt: new Date(slot.startMs),
        offerSlotEndAt: new Date(slot.endMs),
        offerExpiresAt: expiresAt,
        offerStaffId: slot.staffId,
      })
      .where(eq(s.waitlistEntries.id, entry.id));

    await tx.insert(s.auditLog).values({
      businessId,
      action: "waitlist.offered",
      entity: "waitlist_entry",
      entityId: entry.id,
      meta: { staffId: slot.staffId, startMs: slot.startMs },
    });

    await enqueue(tx, {
      businessId,
      topic: "waitlist.offer",
      payload: { entryId: entry.id },
      dedupeKey: `waitlist.offer:${entry.id}:${slot.startMs}`,
    });

    // Self-scheduled deadline: if they have not accepted by then, the offer
    // lapses and the slot is announced again for the next person in line.
    await enqueue(tx, {
      businessId,
      topic: "waitlist.offer_expired",
      payload: { entryId: entry.id },
      dedupeKey: `waitlist.expire:${entry.id}:${slot.startMs}`,
      availableAt: expiresAt,
    });
  });

  return entry.id;
}

type WaitlistEntry = typeof s.waitlistEntries.$inferSelect;

/** Hands an offer's slot to the next person; the worker also releases its hold. */
async function passSlotOn(tx: Tx, entry: WaitlistEntry): Promise<void> {
  const startMs = entry.offerSlotStartAt!.getTime();
  await enqueue(tx, {
    businessId: entry.businessId,
    topic: "waitlist.slot_freed",
    payload: {
      staffId: entry.offerStaffId,
      serviceId: entry.serviceId,
      startMs,
      endMs: entry.offerSlotEndAt!.getTime(),
      releaseHoldToken: entry.offerHoldToken,
    } satisfies FreedSlot,
    dedupeKey: `waitlist.refree:${entry.id}:${startMs}`,
  });
}

/** Called by the worker when an offer's deadline passes. */
export async function expireOffer(entryId: string): Promise<void> {
  const [entry] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.id, entryId));
  if (!entry || entry.status !== "offered") return; // accepted or cancelled already

  await db.transaction(async (tx) => {
    const [lapsed] = await tx
      .update(s.waitlistEntries)
      .set({ status: "expired", offerToken: null, offerExpiresAt: null })
      .where(and(eq(s.waitlistEntries.id, entryId), eq(s.waitlistEntries.status, "offered")))
      .returning({ id: s.waitlistEntries.id });
    if (lapsed) await passSlotOn(tx, entry);
  });
}

export type DeclineResult = { ok: true } | { ok: false; error: "not_found" | "expired" };

/**
 * The client turns the offer down. The status flip is the single point of
 * agreement: however many taps or processes race here, only one of them
 * enqueues the next offer.
 */
export async function declineOffer(token: string): Promise<DeclineResult> {
  const [entry] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.offerToken, token));
  if (!entry) return { ok: false, error: "not_found" };
  if (entry.status === "declined") return { ok: true };
  if (
    entry.status !== "offered" ||
    !entry.offerExpiresAt ||
    entry.offerExpiresAt.getTime() < Date.now()
  ) {
    return { ok: false, error: "expired" };
  }

  const declined = await db.transaction(async (tx) => {
    const [flipped] = await tx
      .update(s.waitlistEntries)
      .set({ status: "declined" })
      .where(and(eq(s.waitlistEntries.id, entry.id), eq(s.waitlistEntries.status, "offered")))
      .returning({ id: s.waitlistEntries.id });
    if (!flipped) return false;

    await tx.insert(s.auditLog).values({
      businessId: entry.businessId,
      action: "waitlist.declined",
      entity: "waitlist_entry",
      entityId: entry.id,
    });
    await passSlotOn(tx, entry);
    return true;
  });
  if (declined) return { ok: true };

  // Lost a race with another tap or the deadline; report what actually happened.
  const [current] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.id, entry.id));
  return current?.status === "declined" ? { ok: true } : { ok: false, error: "expired" };
}

const RELEASE_HOLD_IF_OWNED = `
local raw = redis.call('GET', KEYS[1])
if raw and cjson.decode(raw).token == ARGV[1] then
  return redis.call('DEL', KEYS[1])
end
return 0
`;

async function releaseHold(staffId: string, startMs: number, holdToken: string): Promise<void> {
  await redis().eval(RELEASE_HOLD_IF_OWNED, 1, `hold:${staffId}:${startMs}`, holdToken);
}

export type AcceptResult =
  | { ok: true; bookingId: string }
  | { ok: false; error: "not_found" | "expired" | "slot_taken" };

/** Turns an outstanding offer into a real booking. */
export async function acceptOffer(token: string): Promise<AcceptResult> {
  const [entry] = await db
    .select()
    .from(s.waitlistEntries)
    .where(eq(s.waitlistEntries.offerToken, token));
  if (!entry) return { ok: false, error: "not_found" };
  if (entry.status !== "offered") return { ok: false, error: "expired" };
  if (!entry.offerExpiresAt || entry.offerExpiresAt.getTime() < Date.now()) {
    return { ok: false, error: "expired" };
  }

  const [client] = await db.select().from(s.clients).where(eq(s.clients.id, entry.clientId));
  const holdToken = entry.offerHoldToken;
  if (!holdToken) return { ok: false, error: "expired" };

  const result = await createBooking({
    businessId: entry.businessId,
    staffId: entry.offerStaffId!,
    serviceId: entry.serviceId,
    slot: {
      startMs: entry.offerSlotStartAt!.getTime(),
      endMs: entry.offerSlotEndAt!.getTime(),
    },
    holdToken,
    client: { name: client.name, phone: client.phone },
  });

  if (!result.ok) return { ok: false, error: "slot_taken" };

  await db
    .update(s.waitlistEntries)
    .set({ status: "booked", offerToken: null, offerHoldToken: null })
    .where(eq(s.waitlistEntries.id, entry.id));
  await publishCalendar(entry.businessId, { type: "booking.created", bookingId: result.bookingId });

  return { ok: true, bookingId: result.bookingId };
}

